import {caseResult,shapeResult,rtext,eq,fn,val} from './b36-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,index,pressed=false,extra='')=>`<button type="button" data-x="f36-${action}"${index===undefined?'':` data-index="${esc(index)}"`} aria-pressed="${!!pressed}" ${extra}>${esc(label)}</button>`;
const input=(key,label,value,placeholder='')=>`<label class="f36-field"><span>${esc(label)}</span><input data-xfield="${esc(key)}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off" maxlength="160"></label>`;
const select=(key,label,value,options)=>`<label class="f36-field"><span>${esc(label)}</span><select data-xfield="${esc(key)}"><option value="">选择</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const caption=s=>`<div class="f36-caption">${esc(s)}</div>`;
function shape(t,m){const b=m.board,[a,h]=b.dims,k=28,x=210-a*k/2,y=150+h*k/2,right=x+a*k,top=y-h*k,geometry=t.kind==='rectangle'?`<rect x="${x}" y="${top}" width="${a*k}" height="${h*k}" fill="#d7e9db" stroke="#638b79" stroke-width="3"/>`:`<polygon points="${x},${y} ${right},${y} ${x},${top}" fill="#d7e9db" stroke="#638b79" stroke-width="3"/><path d="M${x+14} ${y}v-14h-14" fill="none" stroke="#7c7184" stroke-width="2"/>`;const last=b.trials.at(-1),fresh=last&&JSON.stringify(last.dims)===JSON.stringify(b.dims)&&eq(last.answer,m.value);return `${caption(t.kind==='rectangle'?'改变长和宽，看看外边一圈':'改变底和垂直高度，看看里面') }<svg viewBox="0 0 420 310" class="f36-shape" aria-label="${t.kind==='rectangle'?'长方形':'三角形'}，底 ${a}，${t.kind==='rectangle'?'宽':'垂直高'} ${h} 厘米">${geometry}<text x="${(x+right)/2}" y="${y+25}" text-anchor="middle">${t.kind==='rectangle'?'长':'底'} ${a} cm</text><text x="${x-12}" y="${(top+y)/2}" text-anchor="end">${t.kind==='rectangle'?'宽':'高'} ${h} cm</text></svg>${last&&!fresh?'<p>图形或猜想改了，再看看。</p>':last?`<p>这次是 ${esc(last.result)} ${t.kind==='rectangle'?'cm':'cm²'}。${last.correct?'和你的猜想一致。':'再比较自己的想法。'}</p>`:''}`;}
function subText(t,c){if(t.kind==='physical')return `${c.u}＋${c.a}×${c.t}`;return t.substitution.replaceAll('{x}',String(c.x).replace('-', '−'));}
function evaluate(t,m){const b=m.board,c=t.cases[b.selected],last=b.trials.at(-1),fresh=last&&last.case===b.selected&&eq(last.answer,m.value);return `${caption('把数放进去，再看会出来什么')}<div class="f36-equation">${esc(t.label)}</div><div class="f36-substitution">${esc(subText(t,c))}</div>${last&&!fresh?'<p>输入或结果改了，再试一次。</p>':last?`<p>这次得到 ${esc(last.result)}。${last.correct?'和你的记录一致。':'再看看括号和运算顺序。'}</p>`:''}`;}
const P=36,S=32,coord=([x,y])=>[P+(x+5)*S,P+(5-y)*S];
function planeBase(hit=false,step=1){let s='';for(let i=-5;i<=5;i++){const[x1,y1]=coord([i,-5]),[x2,y2]=coord([i,5]),[x3,y3]=coord([-5,i]),[x4,y4]=coord([5,i]);s+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${i===0?'f36-axis':'f36-grid'}"/><line x1="${x3}" y1="${y3}" x2="${x4}" y2="${y4}" class="${i===0?'f36-axis':'f36-grid'}"/><text x="${x1}" y="${y1+17}" text-anchor="middle">${i}</text><text x="${x3-9}" y="${y3+4}" text-anchor="end">${i}</text>`;}if(hit){const n=Math.round(10/step);for(let i=0;i<=n;i++)for(let j=0;j<=n;j++){const x=-5+i*step,y=-5+j*step,[px,py]=coord([x,y]);s+=`<circle class="f36-hit" data-x="f36-point" data-px="${x}" data-py="${y}" cx="${px}" cy="${py}" r="${Math.min(11,S*step*.42)}" tabindex="0" role="button" aria-label="点 ${x}，${y}"/>`;}}return s;}
const dot=(p,fill='#bd806e')=>{const[x,y]=coord(p);return `<circle cx="${x}" cy="${y}" r="6" fill="${fill}" stroke="white" stroke-width="2" pointer-events="none"/>`;};
function plane(t,m){const b=m.board,show=t.mode==='read'?t.targets.map(p=>dot(p,'#b5849e')).join(''):'';return `${caption('先看横向，再看纵向；每格是1')}<svg viewBox="0 0 396 396" class="f36-graph" aria-label="四个方向的坐标平面">${planeBase(t.mode==='place',1)}${show}${b.points.map(p=>dot(p)).join('')}</svg><p class="f36-note">${t.mode==='read'?'读出图上那个点。':'点位置，或在下面写一对数。'} ${b.points.length?`已放 ${b.points.length} 个点。`:''}</p>`;}
const linePath=(a,b,c)=>{const points=[];for(let i=0;i<=120;i++){const x=-5+i/12,y=a*x*x+b*x+c,[px,py]=coord([x,y]);points.push(`${i?'L':'M'}${px.toFixed(2)},${py.toFixed(2)}`);}return points.join(' ');};
function plot(t,m){const b=m.board,pts=b.points.slice().sort((a,c)=>a[0]-c[0]);let curve='';if(pts.length>=3){curve=`<path d="${linePath(val(t.a),val(t.b),val(t.c))}" class="f36-line" clip-path="url(#f36-clip)"/>`;}const rows=pts.map(([x,y])=>`<span>(${esc(x)}，${esc(y)})</span>`).join('');return `${caption('先产生数对，再放到图上；每格是1')}<div class="f36-graph-wrap"><svg viewBox="0 0 396 396" class="f36-graph" aria-label="输入和输出的坐标图"><defs><clipPath id="f36-clip"><rect x="${P}" y="${P}" width="${S*10}" height="${S*10}"/></clipPath></defs>${planeBase(true,t.step||1)}${curve}${t.rootSelect&&b.points.length===t.xs.length?b.points.map((p,i)=>{const[x,y]=coord(p);return `<circle data-x="f36-root" data-index="${i}" cx="${x}" cy="${y}" r="9" class="f36-select ${b.roots.includes(i)?'on':''}" tabindex="0" role="button" aria-label="圈出点 ${p[0]}，${p[1]}"/>`;}).join(''):pts.map(p=>dot(p)).join('')}</svg><div><div class="f36-equation">${esc(t.label)}</div><div class="f36-pairs">${rows||'<span>还没有数对</span>'}</div>${curve?'<p class="f36-note">曲线或直线由系统按规则绘出，用来继续观察。</p>':''}${t.rootSelect&&b.points.length===t.xs.length?'<p>点图上的点，圈出与横轴相交的位置。</p>':''}</div></div>`;}
function live(t,m){const b=m.board;if(t.mode==='speed')return speed(t,b);const a=t.mode==='quadratic'?b.a:0,k=t.mode==='quadratic'?0:b.m;let traces=b.views.map(v=>`<path d="${linePath(t.mode==='quadratic'?(v.a??b.a):0,t.mode==='quadratic'?0:(v.m??b.m),v.c??b.c)}" class="f36-saved-line"/>`).join('');return `${caption('改变一个数，图线会怎样？')}<div class="f36-graph-wrap"><svg viewBox="0 0 396 396" class="f36-graph" aria-label="随参数变化的图线"><defs><clipPath id="f36-clip"><rect x="${P}" y="${P}" width="${S*10}" height="${S*10}"/></clipPath></defs>${planeBase(false)}<g clip-path="url(#f36-clip)">${traces}<path d="${linePath(a,k,b.c)}" class="f36-line"/></g></svg><div><div class="f36-equation">${t.mode==='quadratic'?`y＝${b.a}x² ${b.c<0?'− '+Math.abs(b.c):'＋ '+b.c}`:`y＝${b.m}x ${b.c<0?'− '+Math.abs(b.c):'＋ '+b.c}`}</div><p>${t.mode==='quadratic'?`平方前的数：${b.a}`:`每步变化：${b.m}；起点：${b.c}`}</p><p>已留下 ${b.views.length} 种情况。</p><div class="f36-pairs">${b.views.map(x=>`<span>${Object.entries(x).map(([k,v])=>`${({m:'每步变化',c:'起点',a:'平方前的数'}[k]||k)}＝${v}`).join('，')}</span>`).join('')}</div><p class="f36-note">淡线是已留下的情况。</p></div></div>`;}
function speed(t,b){const time=b.time,x=42+time*46,yA=318-6*time*6,yB=318-(4*time+10)*6,ticks=Array.from({length:8},(_,i)=>`<line x1="${42+i*46}" y1="318" x2="${42+i*46}" y2="28" class="f36-grid"/><text x="${42+i*46}" y="335" text-anchor="middle">${i}</text>`).join('')+Array.from({length:10},(_,i)=>`<line x1="42" y1="${318-i*30}" x2="364" y2="${318-i*30}" class="f36-grid"/><text x="33" y="${322-i*30}" text-anchor="end">${i*5}</text>`).join('');return `${caption('两人同时出发：位置高，一定更快吗？')}<div class="f36-graph-wrap"><svg viewBox="0 0 400 355" class="f36-graph" aria-label="两种虚拟速度和位置的比较">${ticks}<line x1="42" y1="318" x2="365" y2="318" class="f36-axis"/><line x1="42" y1="318" x2="42" y2="28" class="f36-axis"/><path d="M42 318 L364 66" class="f36-speed-purple"/><path d="M42 258 L364 90" class="f36-second-line"/><line x1="${x}" y1="318" x2="${x}" y2="35" stroke="#c7bdc8" stroke-dasharray="5 5"/><circle cx="${x}" cy="${yA}" r="6" fill="#7f68a3"/><circle cx="${x}" cy="${yB}" r="6" fill="#4e8f7c"/><text x="345" y="352">时间</text><text x="8" y="31">位置</text></svg><div><p>时间：${time}</p><p>紫色：每次前进6，位置 ${6*time}</p><p>绿色：起点10、每次前进4，位置 ${4*time+10}</p><p class="f36-note">模拟数据；横向每格1，纵向按相同的5单位标度比较。</p></div></div>`;}
function ratio(t,m){const b=m.board;return `${caption('从左边的点到右边的点，分别看横向和纵向')}<svg viewBox="0 0 396 396" class="f36-graph" aria-label="选择两个点，观察横纵变化">${planeBase(false)}${t.points.map((p,i)=>{const[x,y]=coord(p);return `<circle data-x="f36-select" data-index="${i}" cx="${x}" cy="${y}" r="11" class="f36-select ${b.selected.includes(i)?'on':''}" tabindex="0" role="button" aria-label="选点 ${p[0]}，${p[1]}"/><text x="${x+12}" y="${y-10}">${i===0?'A':'B'}(${p.join(',')})</text>`;}).join('')}</svg>`;}
function form(t,m){const last=m.board.trials.at(-1),fresh=last&&JSON.stringify(last.fields)===JSON.stringify({value:m.value,second:m.second,third:m.third});return `${caption('换一个量放到等号的一边')}<div class="f36-equation">${esc(t.display)}</div><p>${esc(t.explain)}</p>${last&&!fresh?'<p>写法改了，再检查一次。</p>':last?`<p>${last.correct?'这次写法与关系对应上了。':'再看每一项和适用条件。'}</p>`:''}`;}
export function visual(t,m){const v=t.type==='x-f36-shape'?shape(t,m):t.type==='x-f36-eval'?evaluate(t,m):t.type==='x-f36-coord'?plane(t,m):t.type==='x-f36-live'?live(t,m):t.type==='x-f36-plot'?plot(t,m):t.type==='x-f36-ratio'?ratio(t,m):t.type==='x-f36-form'?form(t,m):'';return `<div class="f36-world">${v}</div>`;}
export function controls(t,m){const b=m.board;let s='<div class="f36-controls">';
 if(t.type==='x-f36-shape')s+=`<div class="f36-buttons">${btn('dim',(t.kind==='rectangle'?'长':'底')+' −','0,-1')}${btn('dim',(t.kind==='rectangle'?'长':'底')+' ＋','0,1')}${btn('dim',(t.kind==='rectangle'?'宽':'高')+' −','1,-1')}${btn('dim',(t.kind==='rectangle'?'宽':'高')+' ＋','1,1')}</div>`+input('value',t.kind==='rectangle'?'你猜一圈多少 cm':'你猜里面多少 cm²',m.value)+btn('trial','看看结果');
 if(t.type==='x-f36-eval')s+=`<div class="f36-buttons">${t.cases.map((c,i)=>btn('case',c.label,i,b.selected===i)).join('')}</div>`+input('value','你算出多少',m.value)+btn('trial','看看结果');
 if(t.type==='x-f36-coord'||t.type==='x-f36-plot')s+=input('value','横向 x',m.value)+input('second','纵向 y',m.second)+btn('point','放下这个点')+btn('undo','拿回最后一个点');
 if(t.type==='x-f36-live')s+=`<div class="f36-buttons">${t.controls.map(k=>btn('change',({m:'每步变化',c:'起点',a:'平方前的数',time:'时间'}[k])+' −',`${k},-1`)+btn('change',({m:'每步变化',c:'起点',a:'平方前的数',time:'时间'}[k])+' ＋',`${k},1`)).join('')}${btn('save',t.mode==='speed'?'留下这个时刻':'留下这条线')}</div>`;
 if(t.type==='x-f36-ratio')s+='<p>先选图上的两个点，再分别写下横向和纵向变化。</p>';
 if(t.type==='x-f36-form')s+=t.mode==='roots'?select('value','平方反推会有几个方向',m.value,[['both','正负两个方向'],['positive','只有正方向']])+input('second','一个结果',m.second)+input('third','另一个结果',m.third)+btn('form','检查这次写法'):t.mode==='fraction'?input('value','分子',m.value,'例如 2A')+input('second','分母',m.second,'例如 b')+btn('form','检查这次写法'):input('value',t.subject+' 等于',m.value,t.placeholder||'写出右边')+btn('form','检查这次写法');
 for(const[i,q]of(t.questions||[]).entries())s+=q.options?select('answers.'+i,q.label,m.answers[i],q.options):input('answers.'+i,q.label,m.answers[i],q.placeholder||'');
 if(m.issue)s+=`<p class="f36-issue" role="status">${esc(m.issue)}</p>`;
 return s+`<details><summary>留下自己的想法（可选）</summary>${input('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
